
.pro-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.pro-item {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.pro-key {
  width: 40px;
  font-weight: bold;
  color: var(--c-primary);
}

.pro-val {
  flex: 1;
  color: var(--c-text);
}

.status.ok {
  color: var(--c-success);
}

.status.warning {
  color: var(--c-warning);
}

.status.danger {
  color: var(--c-danger);
  font-weight: bold;
}
