
.rel-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.rel-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.rel-name {
  width: 52px;
  font-weight: bold;
  color: var(--c-text);
}

.rel-type {
  width: 26px;
  font-size: 11px;
  color: var(--c-text-muted);
}

.rel-track {
  flex: 1;
  height: 10px;
  background: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 999px;
  overflow: hidden;
}

.rel-fill {
  height: 100%;
  transition: width 0.4s ease;
}

.rel-value {
  width: 30px;
  text-align: right;
  font-size: 12px;
  color: var(--c-text-muted);
}
