
.stage-bar {
  padding: 10px 14px;
  border-bottom: 1px solid var(--c-border);
}

.stages {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
}

.stage-item {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--c-text-muted);
  font-size: 12px;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--c-border);
  border: 1.5px solid var(--c-text-muted);
}

.stage-item.on {
  color: var(--c-primary);
  font-weight: bold;
}

.stage-item.on .dot {
  background: var(--c-primary);
  border-color: var(--c-primary);
  box-shadow: 0 0 0 3px var(--c-primary-soft);
}

.seed-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.seed-label {
  font-size: 12px;
  color: var(--c-accent);
  font-weight: bold;
  white-space: nowrap;
}

.seed-track {
  flex: 1;
  height: 12px;
  background: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 999px;
  overflow: hidden;
}

.seed-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-accent), #e8b84a);
  transition: width 0.5s ease;
}

.seed-count {
  font-size: 12px;
  color: var(--c-text-muted);
  white-space: nowrap;
}
