
.tab-nav {
  display: flex;
  gap: 6px;
  padding: 8px 14px 0;
}

.tab {
  border: 1.5px solid var(--c-border);
  background: var(--c-bg);
  color: var(--c-text-muted);
  padding: 5px 16px;
  border-radius: 8px 8px 0 0;
  font-size: 12px;
  cursor: pointer;
  font-family: var(--font-ui);
}

.tab.active {
  background: var(--c-primary);
  border-color: var(--c-primary);
  color: #fff;
  font-weight: bold;
}
